-- ============================================================
-- SoftStock — HISTORY CORRECTION for May–August 2026
-- Replaces the May 1 – Aug 31 stock_log rows (originally taken from
-- the 'Stock Log' tab, which was incomplete for those months) with
-- rows rebuilt from the daily Usage/Receipt columns of the May/June/
-- July/August sheets — the source the old dashboard actually used,
-- and confirmed to match its totals for those months.
-- Replaces with 1356 rows. Run once, after migration.sql / migration_topup.sql.
-- ============================================================

alter table products add column if not exists import_key text;

-- ---------------- remove the old (incomplete) May–Aug history ----------------
delete from stock_log where date >= '2026-05-01' and date <= '2026-08-31';

-- ---------------- tag products for matching ----------------
update products set import_key = 'ռուլոն սպիտակ|facial tissue|20.0|3.0|14.0' where name = 'Ռուլոն սպիտակ' and type = 'Facial Tissue' and coalesce(width_cm,-1) = coalesce(20.0,-1) and ply = 3 and coalesce(gsm,-1) = coalesce(14.0,-1) and import_key is null;
